int Helper(int amount, int scale) {
    return amount * scale;
}

files.Probe.SC2Mod/Base.SC2Data/MapScript.gala:
include "Lib"

const int c_limit = 3;
struct Pair {
    int left;
    int right;
};

void Init() {
    int x = Helper(2, c_limit);
    Pair p;
    p.left = Helper(x, 1);
}

